  const opaque = [
    [/\bimport\(\s*(?!['"][^'"]*['"]\s*\))/, 'a computed dynamic import'],
    [/\brequire\s*\(|\bcreateRequire\b/, 'require()'],
    [/\breadFile(?:Sync)?\s*\(|\bnode:fs\b|['"]fs(?:\/promises)?['"]/, 'a file-system read'],
    [/\bvm\.|\bnew Function\b|\beval\s*\(/, 'evaluated code'],
  ]
