function eventLabel(event) {
  if (event === null || typeof event !== 'object' || Array.isArray(event)) return JSON.stringify(event)
  const fields = Object.entries(event)
    .filter(([key]) => key !== '$')
    .map(([key, value]) => `${key}:${JSON.stringify(value)}`)
  return fields.length === 0 ? event.$ : `${event.$}{${fields.join(',')}}`
}

// 기대값은 모델이 동기로 계산했다. await는 제품 쪽 adapter 호출에만 붙고, dispose는 실패해도 다음 case 전에 돈다.
// 결합 케이스는 세계 조건으로 시작한다 — 매개변수가 없는 init은 기본 fixture로 돌아 공허하게 통과할 것이다.
async function drive(trace, expected, coordinates) {
  if (coordinates !== undefined && adapter.init.length < 1)
    throw new Error('ADAPTER_JOINT_UNSUPPORTED: init declares no coordinates parameter (a parameter with a default value is not counted)')
  let state = await within(coordinates === undefined ? adapter.init() : adapter.init(structuredClone(coordinates)), 'init')
  try {
    assert.deepEqual(await within(adapter.observe(state), 'initial observe'), INITIAL, 'initial observation')
    for (const [index, event] of trace.entries()) {
      const where = 'step ' + (index + 1) + ' (' + eventLabel(event) + ') of ' + trace.map(eventLabel).join(' · ')
      state = await within(adapter.step(state, structuredClone(event)), where)
      assert.deepEqual(await within(adapter.observe(state), where), expected[index], where)
    }
  } finally {
    if (adapter.dispose) await within(adapter.dispose(state), 'dispose')
  }
}

for (const entry of CASES) {
  test('[' + ROW + '] [' + entry.id + '] ' + entry.label, UNLIMITED, () => drive(entry.trace, entry.observations, entry.coordinates))
}

const RUNS = 300
const FIRST = 150
const BOUND = 3
const BEYOND_REACHABLE = true
const CLASSES = {"state.$":{"\"Failed\"":"\"Failed\"","\"Rejected\"":"\"Rejected\"","\"Requested\"":"\"Requested\"","\"Running\"":"\"Running\"","\"Succeeded\"":"\"Succeeded\""},"Start.$":{"\"Start\"":"\"Start\""},"Start.registered":{"false":"false","true":"true"},"Start.allowed":{"false":"false","true":"true"},"Start.valid":{"false":"false","true":"true"},"Start.free":{"false":"false","true":"true"},"observation.$":{"\"Failed\"":"\"Failed\"","\"Rejected\"":"\"Rejected\"","\"Requested\"":"\"Requested\"","\"Running\"":"\"Running\"","\"Succeeded\"":"\"Succeeded\""},"Finish.$":{"\"Finish\"":"\"Finish\""},"Finish.ok":{"false":"false","true":"true"},"Finish.valid":{"false":"false","true":"true"},"Cancel.$":{"\"Cancel\"":"\"Cancel\""}}
const ITEMS = ["Cancel.$=\"Cancel\"","Cancel.$=\"Cancel\" × state.$=\"Failed\"","Cancel.$=\"Cancel\" × state.$=\"Rejected\"","Cancel.$=\"Cancel\" × state.$=\"Requested\"","Cancel.$=\"Cancel\" × state.$=\"Running\"","Cancel.$=\"Cancel\" × state.$=\"Succeeded\"","Finish.$=\"Finish\"","Finish.$=\"Finish\" × state.$=\"Failed\"","Finish.$=\"Finish\" × state.$=\"Rejected\"","Finish.$=\"Finish\" × state.$=\"Requested\"","Finish.$=\"Finish\" × state.$=\"Running\"","Finish.$=\"Finish\" × state.$=\"Succeeded\"","Finish.ok=false","Finish.ok=false × state.$=\"Failed\"","Finish.ok=false × state.$=\"Rejected\"","Finish.ok=false × state.$=\"Requested\"","Finish.ok=false × state.$=\"Running\"","Finish.ok=false × state.$=\"Succeeded\"","Finish.ok=true","Finish.ok=true × state.$=\"Failed\"","Finish.ok=true × state.$=\"Rejected\"","Finish.ok=true × state.$=\"Requested\"","Finish.ok=true × state.$=\"Running\"","Finish.ok=true × state.$=\"Succeeded\"","Finish.valid=false","Finish.valid=false × state.$=\"Failed\"","Finish.valid=false × state.$=\"Rejected\"","Finish.valid=false × state.$=\"Requested\"","Finish.valid=false × state.$=\"Running\"","Finish.valid=false × state.$=\"Succeeded\"","Finish.valid=true","Finish.valid=true × state.$=\"Failed\"","Finish.valid=true × state.$=\"Rejected\"","Finish.valid=true × state.$=\"Requested\"","Finish.valid=true × state.$=\"Running\"","Finish.valid=true × state.$=\"Succeeded\"","Start.$=\"Start\"","Start.$=\"Start\" × state.$=\"Failed\"","Start.$=\"Start\" × state.$=\"Rejected\"","Start.$=\"Start\" × state.$=\"Requested\"","Start.$=\"Start\" × state.$=\"Running\"","Start.$=\"Start\" × state.$=\"Succeeded\"","Start.allowed=false","Start.allowed=false × state.$=\"Failed\"","Start.allowed=false × state.$=\"Rejected\"","Start.allowed=false × state.$=\"Requested\"","Start.allowed=false × state.$=\"Running\"","Start.allowed=false × state.$=\"Succeeded\"","Start.allowed=true","Start.allowed=true × state.$=\"Failed\"","Start.allowed=true × state.$=\"Rejected\"","Start.allowed=true × state.$=\"Requested\"","Start.allowed=true × state.$=\"Running\"","Start.allowed=true × state.$=\"Succeeded\"","Start.free=false","Start.free=false × state.$=\"Failed\"","Start.free=false × state.$=\"Rejected\"","Start.free=false × state.$=\"Requested\"","Start.free=false × state.$=\"Running\"","Start.free=false × state.$=\"Succeeded\"","Start.free=true","Start.free=true × state.$=\"Failed\"","Start.free=true × state.$=\"Rejected\"","Start.free=true × state.$=\"Requested\"","Start.free=true × state.$=\"Running\"","Start.free=true × state.$=\"Succeeded\"","Start.registered=false","Start.registered=false × state.$=\"Failed\"","Start.registered=false × state.$=\"Rejected\"","Start.registered=false × state.$=\"Requested\"","Start.registered=false × state.$=\"Running\"","Start.registered=false × state.$=\"Succeeded\"","Start.registered=true","Start.registered=true × state.$=\"Failed\"","Start.registered=true × state.$=\"Rejected\"","Start.registered=true × state.$=\"Requested\"","Start.registered=true × state.$=\"Running\"","Start.registered=true × state.$=\"Succeeded\"","Start.valid=false","Start.valid=false × state.$=\"Failed\"","Start.valid=false × state.$=\"Rejected\"","Start.valid=false × state.$=\"Requested\"","Start.valid=false × state.$=\"Running\"","Start.valid=false × state.$=\"Succeeded\"","Start.valid=true","Start.valid=true × state.$=\"Failed\"","Start.valid=true × state.$=\"Rejected\"","Start.valid=true × state.$=\"Requested\"","Start.valid=true × state.$=\"Running\"","Start.valid=true × state.$=\"Succeeded\"","observation.$=\"Failed\"","observation.$=\"Rejected\"","observation.$=\"Requested\"","observation.$=\"Running\"","observation.$=\"Succeeded\""]
const EVENT_KINDS = ["Cancel","Finish","Start"]
function leaves(value, path, found = []) {
  if (Array.isArray(value)) found.push([`${path}.length`, value.length])
  else if (value !== null && typeof value === 'object')
    for (const [key, field] of Object.entries(value)) leaves(field, `${path}.${key}`, found)
  else found.push([path, value])
  return found
}
function allowed(raw) {
  const items = []
  for (let cursor = call('next', raw.reduceRight((tail, head) => ({ $: 'Con', head, tail }), { $: 'Nil' })); cursor?.$ === 'Con'; cursor = cursor.tail) items.push(cursor.head)
  return items
}

// 표본의 매 단계를 최소 묶음과 같은 류로 센다. 이름표에 없는 값(bound 밖에서 처음 나온 값)은 unseen 류다.
function classOf([path, value]) {
  const name = CLASSES[path]?.[JSON.stringify(value)]
  return path + '=' + (name ?? 'unseen:' + JSON.stringify(value))
}
function itemsOfStep(state, event, observation) {
  const states = leaves(toPlain(state), 'state').map(classOf)
  const events = leaves(event, event.$ ?? 'event').map(classOf)
  const observed = leaves(observation, 'observation').map(classOf)
  return [...events, ...observed, ...events.flatMap((left) => states.map((right) => left + ' × ' + right))]
}

// 두 단계: 1단계는 균등하게 뽑으며 항목별 횟수를 세고, 2단계는 그 횟수를 얼려 덜 밟은 항목을 덮는 사건에 가중치를
// 준다. 가중치는 2단계 안에서 바뀌지 않으므로 같은 입력은 같은 trace다 — shrink가 결정적으로 남는다.
// swarm: 실행마다 쓸 사건 종류의 부분집합도 입력이다. 남은 사건끼리 더 깊이 섞인다. 허용 사건이 모두 빠지면 전부 쓴다.
const hits = new Map()
let frozen = null
function weightOf(state, event) {
  const observation = toPlain(call('observe', call('step', state, event)))
  return itemsOfStep(state, toPlain(event), observation).reduce((sum, item) => sum + 1 / (1 + (frozen.get(item) ?? 0)), 0)
}
function pick(choices, index, state) {
  if (frozen === null) return choices[index % choices.length]
  const scores = choices.map((event) => weightOf(state, event))
  let left = ((index % 1_000_000) / 1_000_000) * scores.reduce((sum, score) => sum + score, 0)
  for (const [position, score] of scores.entries()) {
    left -= score
    if (left < 0) return choices[position]
  }
  return choices.at(-1)
}
const lengths = []
async function sample({ enabled, indices }) {
  const raw = []
  const expected = []
  let state = call('init')
  for (const index of indices) {
    const all = allowed(raw)
    if (all.length === 0) break
    const swarm = all.filter((event) => enabled.includes(event.$) || !EVENT_KINDS.includes(event.$))
    const event = pick(swarm.length > 0 ? swarm : all, index, state)
    const next = call('step', state, event)
    const observation = toPlain(call('observe', next))
    for (const item of itemsOfStep(state, toPlain(event), observation)) hits.set(item, (hits.get(item) ?? 0) + 1)
    raw.push(event)
    expected.push(observation)
    state = next
  }
  lengths.push(raw.length)
  await drive(raw.map(toPlain), expected)
}

// 선택 인덱스는 0..2^31-1이다 — 고정된 작은 범위를 modulo하면 그보다 많은 선택지 가운데 일부가 영원히 뽑히지 않는다.
// 실제로 실행한 길이를 센다: 뽑은 배열이 bound보다 길어도 환경이 일찍 끝나면 bound 밖을 검사한 것이 아니다.
test('[' + ROW + '] sampled traces (fast-check)', UNLIMITED, async () => {
  const input = fc.record({
    enabled: fc.subarray(EVENT_KINDS, { minLength: 1 }),
    indices: fc.array(fc.nat(), { minLength: 4, maxLength: 6 }),
  })
  await fc.assert(fc.asyncProperty(input, sample), { numRuns: FIRST, seed: 452510879 })
  if (RUNS > FIRST) {
    frozen = new Map(hits)
    await fc.assert(fc.asyncProperty(input, sample), { numRuns: RUNS - FIRST, seed: 452510880 })
  }
  const beyond = lengths.filter((length) => length > BOUND).length
  console.log(JSON.stringify({ fastCheck: { row: ROW, requested: RUNS, executed: lengths.length, beyondBound: beyond, longest: Math.max(...lengths), seed: 452510879, stages: [FIRST, RUNS - FIRST] } }))
  // 커버리지: 0번 밟은 항목, Good-Turing(다음 실행이 못 본 항목을 밟을 확률 ≈ 한 번만 본 항목 수 / 전체 관측 수),
  // 3의 법칙(한 번도 안 나온 사건의 확률은 95% 신뢰도로 3/N 이하). 판정이 아니라 어디가 얇은지 보여 준다.
  const counts = [...hits.values()]
  const total = counts.reduce((sum, count) => sum + count, 0)
  const zero = ITEMS.filter((item) => !hits.has(item))
  const unseen = [...hits.keys()].filter((item) => item.includes('=unseen:'))
  console.log(JSON.stringify({ coverage: { row: ROW, items: ITEMS.length, hit: ITEMS.length - zero.length, zero: zero.slice(0, 20), zeroCount: zero.length, goodTuring: total === 0 ? 1 : counts.filter((count) => count === 1).length / total, ruleOfThree: 3 / lengths.length, unseen: unseen.slice(0, 20) } }))
  assert.ok(lengths.length >= RUNS, 'fast-check executed ' + lengths.length + ' of ' + RUNS + ' requested runs')
  if (BEYOND_REACHABLE) assert.ok(beyond > 0, 'no sampled trace passed the bound — the sampled claim beyond the bound would be false')
})
